/**
 * YAML file validator module.
 *
 * Provides syntax validation and basic structural checks for YAML files
 * using Bun's built-in YAML parsing module. No external dependencies required.
 */

import { parse as parseYaml } from "bun:yaml";

/**
 * Represents a single validation error found in a YAML file.
 */
export interface ValidationError {
  /** The file path where the error occurred */
  file: string;
  /** Line number where the error was detected (1-indexed) */
  line?: number;
  /** Column number where the error was detected (1-indexed) */
  column?: number;
  /** Human-readable error message */
  message: string;
  /** Severity level: 'error' for critical issues, 'warning' for minor issues */
  severity: "error" | "warning";
}

/**
 * Represents the validation result for a single file.
 */
export interface ValidationResult {
  /** The file path that was validated */
  file: string;
  /** Whether the file passed validation */
  valid: boolean;
  /** Array of validation errors found (empty if valid) */
  errors: ValidationError[];
}

/**
 * Validates one or more YAML files for syntax and basic structural integrity.
 *
 * @param filePaths - Array of file paths to validate
 * @returns Promise resolving to array of ValidationResult objects, one per file
 *
 * @example
 * const results = await validateYamlFiles(['config.yml', 'db.yml']);
 * results.forEach(r => {
 *   if (!r.valid) console.log(`${r.file} has errors:`, r.errors);
 * });
 */
export async function validateYamlFiles(
  filePaths: string[]
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    try {
      // Read file using Bun.file()
      const file = Bun.file(filePath);
      const content = await file.text();

      // Attempt to parse YAML
      let parsed: unknown;
      let parseError: ValidationError | null = null;

      try {
        parsed = parseYaml(content);
      } catch (error) {
        // Capture parse error with line/column information
        const errorObj = error as Record<string, unknown>;
        parseError = {
          file: filePath,
          line: (errorObj.line as number) ?? undefined,
          column: (errorObj.column as number) ?? undefined,
          message: (errorObj.message as string) ?? String(error),
          severity: "error",
        };
      }

      if (parseError) {
        results.push({
          file: filePath,
          valid: false,
          errors: [parseError],
        });
      } else {
        // Run structural validation on parsed object
        const structuralErrors = validateStructure(filePath, parsed, content);
        results.push({
          file: filePath,
          valid: structuralErrors.length === 0,
          errors: structuralErrors,
        });
      }
    } catch (error) {
      // Handle file I/O errors
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      results.push({
        file: filePath,
        valid: false,
        errors: [
          {
            file: filePath,
            message: errorMessage,
            severity: "error",
          },
        ],
      });
    }
  }

  return results;
}

/**
 * Detects structural issues in parsed YAML content.
 *
 * Currently checks for duplicate keys at the same nesting level,
 * which is a common YAML error that can lead to unexpected behavior.
 *
 * @param filePath - The file path (used in error messages)
 * @param parsed - The parsed YAML object
 * @param content - The original YAML content (used for line tracking)
 * @returns Array of structural validation errors
 */
function validateStructure(
  filePath: string,
  parsed: unknown,
  content: string
): ValidationError[] {
  const errors: ValidationError[] = [];

  // Check for duplicate keys in mappings
  const duplicates = findDuplicateKeys(parsed);
  for (const dup of duplicates) {
    const lineNum = findLineNumber(content, dup.path);
    errors.push({
      file: filePath,
      line: lineNum,
      message: `Duplicate key '${dup.key}' in mapping`,
      severity: "error",
    });
  }

  return errors;
}

/**
 * Finds duplicate keys in a parsed YAML object.
 *
 * @param obj - The parsed YAML object to analyze
 * @param path - Current traversal path (used internally for recursion)
 * @returns Array of duplicate key information
 */
function findDuplicateKeys(
  obj: unknown,
  path: string[] = []
): Array<{ key: string; path: string[] }> {
  const duplicates: Array<{ key: string; path: string[] }> = [];

  if (obj && typeof obj === "object" && !Array.isArray(obj)) {
    const keys = Object.keys(obj);
    const seenKeys = new Set<string>();

    for (const key of keys) {
      if (seenKeys.has(key)) {
        duplicates.push({
          key,
          path: [...path, key],
        });
      }
      seenKeys.add(key);
    }

    // Recursively check nested objects
    for (const key of keys) {
      const value = (obj as Record<string, unknown>)[key];
      if (value && typeof value === "object") {
        duplicates.push(
          ...findDuplicateKeys(value, [...path, key])
        );
      }
    }
  }

  return duplicates;
}

/**
 * Attempts to find the line number where a key appears in YAML content.
 *
 * Uses a simple heuristic: finds the first occurrence of "key:" in the content.
 * More sophisticated tracking would require full AST analysis.
 *
 * @param content - The original YAML content
 * @param path - The path to the key (e.g., ['root', 'nested'])
 * @returns Line number (1-indexed), or undefined if not found
 */
function findLineNumber(content: string, path: string[]): number | undefined {
  if (path.length === 0) return undefined;

  const lines = content.split("\n");
  const searchKey = path[path.length - 1];

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes(`${searchKey}:`)) {
      return i + 1; // 1-indexed line numbers
    }
  }

  return undefined;
}

/**
 * Formats validation results into a human-readable output string.
 *
 * Produces output in the format:
 *   ✓ file.yml
 *   ✗ other.yml: line 5 - error description
 *
 * @param results - Array of ValidationResult objects to format
 * @returns Formatted string suitable for console output
 */
export function formatErrors(results: ValidationResult[]): string {
  const lines: string[] = [];

  for (const result of results) {
    if (result.valid) {
      lines.push(`✓ ${result.file}`);
    } else {
      for (const error of result.errors) {
        const parts = [`✗ ${result.file}`];

        if (error.line) {
          parts.push(`line ${error.line}`);
        }

        parts.push(`- ${error.message}`);
        lines.push(parts.join(": "));
      }
    }
  }

  return lines.join("\n");
}

