import { describe, expect, test, beforeEach, afterEach } from "bun:test";
import { validateYamlFiles, formatErrors } from "./yaml-validator";
import { promises as fs } from "fs";
import { join } from "path";

// Create a temporary directory for test files
const TEST_DIR = "/tmp/yaml-validator-tests";

describe("yaml-validator", () => {
  beforeEach(async () => {
    // Create test directory
    await fs.mkdir(TEST_DIR, { recursive: true });
  });

  afterEach(async () => {
    // Clean up test files
    try {
      const files = await fs.readdir(TEST_DIR);
      for (const file of files) {
        await fs.unlink(join(TEST_DIR, file));
      }
      await fs.rmdir(TEST_DIR);
    } catch (error) {
      // Ignore cleanup errors
    }
  });

  describe("validateYamlFiles", () => {
    test("valid YAML file parses successfully without errors", async () => {
      const testFile = join(TEST_DIR, "valid.yml");
      const content = `name: test
version: 1.0
items:
  - item1
  - item2`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(testFile);
      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("simple valid YAML object is parsed correctly", async () => {
      const testFile = join(TEST_DIR, "simple.yml");
      const content = `key: value
number: 42
boolean: true`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("invalid YAML syntax is detected and reported with error message", async () => {
      const testFile = join(TEST_DIR, "invalid.yml");
      const content = `name: test
unclosed_quote: "value
another_key: value`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(testFile);
      expect(results[0].valid).toBe(false);
      expect(results[0].errors.length).toBeGreaterThan(0);
      expect(results[0].errors[0].message).toBeDefined();
      expect(results[0].errors[0].severity).toBe("error");
    });

    test("invalid YAML syntax error includes line information when available", async () => {
      const testFile = join(TEST_DIR, "invalid-with-line.yml");
      const content = `name: test
unclosed: "value
another: key`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(false);
      expect(results[0].errors.length).toBeGreaterThan(0);
      // Line number may or may not be available depending on parser
      // but message should always be present
      expect(results[0].errors[0].message.length).toBeGreaterThan(0);
    });

    test("bad indentation is detected as syntax error", async () => {
      const testFile = join(TEST_DIR, "bad-indent.yml");
      const content = `name: test
  bad_indent: value
  another: value
    extra_indent: value`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      // This may or may not fail depending on YAML spec strictness
      // but should at minimum not throw
      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(testFile);
    });

    test("multiple valid files are all validated successfully", async () => {
      const file1 = join(TEST_DIR, "valid1.yml");
      const file2 = join(TEST_DIR, "valid2.yml");
      const file3 = join(TEST_DIR, "valid3.yml");

      await fs.writeFile(file1, "key1: value1");
      await fs.writeFile(file2, "key2: value2");
      await fs.writeFile(file3, "key3: value3");

      const results = await validateYamlFiles([file1, file2, file3]);

      expect(results).toHaveLength(3);
      expect(results[0].valid).toBe(true);
      expect(results[1].valid).toBe(true);
      expect(results[2].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
      expect(results[1].errors).toHaveLength(0);
      expect(results[2].errors).toHaveLength(0);
    });

    test("batch validation with one invalid file reports only that file as invalid", async () => {
      const valid = join(TEST_DIR, "batch_valid.yml");
      const invalid = join(TEST_DIR, "batch_invalid.yml");

      await fs.writeFile(valid, "key: value");
      await fs.writeFile(invalid, "unclosed: \"value");

      const results = await validateYamlFiles([valid, invalid]);

      expect(results).toHaveLength(2);
      expect(results[0].valid).toBe(true);
      expect(results[1].valid).toBe(false);
      expect(results[1].errors.length).toBeGreaterThan(0);
    });

    test("missing file is reported with descriptive error message", async () => {
      const nonexistent = join(TEST_DIR, "nonexistent.yml");

      const results = await validateYamlFiles([nonexistent]);

      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(nonexistent);
      expect(results[0].valid).toBe(false);
      expect(results[0].errors.length).toBeGreaterThan(0);
      expect(results[0].errors[0].message).toBeDefined();
    });

    test("empty YAML file is valid", async () => {
      const testFile = join(TEST_DIR, "empty.yml");
      await fs.writeFile(testFile, "");

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("YAML with only comments is valid", async () => {
      const testFile = join(TEST_DIR, "comments.yml");
      const content = `# This is a comment
# Another comment
`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("complex nested YAML structure is parsed correctly", async () => {
      const testFile = join(TEST_DIR, "complex.yml");
      const content = `app:
  name: myapp
  version: 1.0
  config:
    database:
      host: localhost
      port: 5432
      credentials:
        user: admin
        password: secret
    cache:
      enabled: true
      ttl: 3600`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("YAML with array syntax is valid", async () => {
      const testFile = join(TEST_DIR, "array.yml");
      const content = `servers:
  - name: web1
    ip: 192.168.1.1
  - name: web2
    ip: 192.168.1.2
ports: [8080, 8443, 3000]`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });
  });

  describe("formatErrors", () => {
    test("formats error with line number in spec-compliant format", () => {
      const results = [
        {
          file: "config.yml",
          valid: false,
          errors: [
            {
              file: "config.yml",
              line: 5,
              message: "Unexpected token",
              severity: "error" as const,
            },
          ],
        },
      ];

      const output = formatErrors(results);

      expect(output).toBe("config.yml: line 5 - Unexpected token");
    });

    test("formats error without line number correctly", () => {
      const results = [
        {
          file: "db.yml",
          valid: false,
          errors: [
            {
              file: "db.yml",
              message: "File not found",
              severity: "error" as const,
            },
          ],
        },
      ];

      const output = formatErrors(results);

      expect(output).toBe("db.yml: File not found");
    });

    test("formats multiple errors from same file", () => {
      const results = [
        {
          file: "config.yml",
          valid: false,
          errors: [
            {
              file: "config.yml",
              line: 5,
              message: "Error 1",
              severity: "error" as const,
            },
            {
              file: "config.yml",
              line: 10,
              message: "Error 2",
              severity: "error" as const,
            },
          ],
        },
      ];

      const output = formatErrors(results);

      expect(output).toContain("config.yml: line 5 - Error 1");
      expect(output).toContain("config.yml: line 10 - Error 2");
    });

    test("formats errors from multiple files", () => {
      const results = [
        {
          file: "file1.yml",
          valid: false,
          errors: [
            {
              file: "file1.yml",
              line: 3,
              message: "Error in file 1",
              severity: "error" as const,
            },
          ],
        },
        {
          file: "file2.yml",
          valid: false,
          errors: [
            {
              file: "file2.yml",
              line: 7,
              message: "Error in file 2",
              severity: "error" as const,
            },
          ],
        },
      ];

      const output = formatErrors(results);

      expect(output).toContain("file1.yml: line 3 - Error in file 1");
      expect(output).toContain("file2.yml: line 7 - Error in file 2");
    });

    test("returns empty string when no errors", () => {
      const results = [
        {
          file: "valid.yml",
          valid: true,
          errors: [],
        },
      ];

      const output = formatErrors(results);

      expect(output).toBe("");
    });

    test("formats multiple lines with newlines between errors", () => {
      const results = [
        {
          file: "file1.yml",
          valid: false,
          errors: [
            {
              file: "file1.yml",
              line: 2,
              message: "First error",
              severity: "error" as const,
            },
            {
              file: "file1.yml",
              line: 5,
              message: "Second error",
              severity: "error" as const,
            },
          ],
        },
      ];

      const output = formatErrors(results);
      const lines = output.split("\n");

      expect(lines).toHaveLength(2);
      expect(lines[0]).toBe("file1.yml: line 2 - First error");
      expect(lines[1]).toBe("file1.yml: line 5 - Second error");
    });
  });

  describe("integration tests", () => {
    test("valid and invalid files in batch return correct results", async () => {
      const validFile = join(TEST_DIR, "integration_valid.yml");
      const invalidFile = join(TEST_DIR, "integration_invalid.yml");

      await fs.writeFile(validFile, "app:\n  name: test");
      await fs.writeFile(invalidFile, "invalid: \"unclosed");

      const results = await validateYamlFiles([validFile, invalidFile]);
      const formatted = formatErrors(results);

      expect(results[0].valid).toBe(true);
      expect(results[1].valid).toBe(false);
      expect(formatted).toContain(invalidFile);
      expect(formatted).not.toContain(validFile);
    });

    test("error messages are actionable and include all relevant information", async () => {
      const testFile = join(TEST_DIR, "actionable.yml");
      await fs.writeFile(testFile, "key: \"unclosed");

      const results = await validateYamlFiles([testFile]);
      const formatted = formatErrors(results);

      // Should include filename for identification
      expect(formatted).toContain("actionable.yml");
      // Should include some form of error message
      expect(formatted.length).toBeGreaterThan(0);
    });

    test("special characters in filenames are handled correctly", async () => {
      const testFile = join(TEST_DIR, "special-chars_123.yml");
      await fs.writeFile(testFile, "key: value");

      const results = await validateYamlFiles([testFile]);

      expect(results[0].file).toBe(testFile);
      expect(results[0].valid).toBe(true);
    });
  });
});

