   175→      severity: "error",
   176→    });
   177→  }
   178→  if (inSingleQuote) {
   179→    errors.push({
   180→      file: filePath,
   181→      line: lines.length,
   182→      message: 'Unclosed single quote',
   183→      severity: "error",
   184→    });
   185→  }
   186→
   187→  return errors;
   188→}
   189→
   190→
   191→/**
   192→ * Formats validation results into a human-readable output string.
   193→ *
   194→ * Produces output in the format:
   195→ *   filename.yml: line 5 - error description
   196→ *
   197→ * @param results - Array of ValidationResult objects to format
   198→ * @returns Formatted string suitable for console output
   199→ */
   200→export function formatErrors(results: ValidationResult[]): string {
   201→  const lines: string[] = [];
   202→
   203→  for (const result of results) {
   204→    for (const error of result.errors) {
   205→      if (error.line) {
   206→        lines.push(`${result.file}: line ${error.line} - ${error.message}`);
   207→      } else {
   208→        lines.push(`${result.file}: ${error.message}`);
   209→      }
   210→    }
   211→  }
   212→
   213→  return lines.join("\n");
   214→}
