    24→/**
    25→ * Represents the validation result for a single file.
    26→ */
    27→export interface ValidationResult {
    28→  /** The file path that was validated */
    29→  file: string;
    30→  /** Whether the file passed validation */
    31→  valid: boolean;
    32→  /** Array of validation errors found (empty if valid) */
    33→  errors: ValidationError[];
