/**
 * Main entry point for the rp1 eval test project.
 */

import { greet } from "./utils";
import { validateYamlFiles, formatErrors } from "./yaml-validator";

const command = process.argv[2];

// Dispatch to YAML validator command
if (command === "validate-yaml") {
  const files = process.argv.slice(3);

  // Check for --help flag
  if (files.includes("--help")) {
    console.log(`Usage: bun run validate-yaml [--help] <files...>

Validate YAML file syntax and structure.

Examples:
  bun run validate-yaml config.yml
  bun run validate-yaml app.yml db.yml settings.yml
  bun run validate-yaml --help

Exit codes:
  0 - All files valid
  1 - Validation failed or file error`);
    process.exit(0);
  }

  if (files.length === 0) {
    console.error("Usage: bun run validate-yaml <files...>");
    process.exit(1);
  }

  validateYamlFiles(files).then((results) => {
    const output = formatErrors(results);
    if (output) {
      console.log(output);
    }
    const allValid = results.every((r) => r.valid);
    process.exit(allValid ? 0 : 1);
  });
} else {
  // Default behavior: greet the user
  const name = command ?? "World";
  console.log(greet(name));
}

