     1→/**
     2→ * YAML file validator module.
     3→ *
     4→ * Provides syntax validation and basic structural checks for YAML files
     5→ * using Bun's built-in YAML parser. No external dependencies required.
     6→ */
     7→
     8→/**
     9→ * Represents a single validation error found in a YAML file.
    10→ */
    11→export interface ValidationError {
    12→  /** The file path where the error occurred */
    13→  file: string;
    14→  /** Line number where the error was detected (1-indexed) */
    15→  line?: number;
    16→  /** Column number where the error was detected (1-indexed) */
    17→  column?: number;
    18→  /** Human-readable error message */
    19→  message: string;
    20→  /** Severity level: 'error' for critical issues, 'warning' for minor issues */
    21→  severity: "error" | "warning";
    22→}
    23→
    24→/**
    25→ * Represents the validation result for a single file.
    26→ */
    27→export interface ValidationResult {
    28→  /** The file path that was validated */
    29→  file: string;
    30→  /** Whether the file passed validation */
    31→  valid: boolean;
    32→  /** Array of validation errors found (empty if valid) */
    33→  errors: ValidationError[];
    34→}
    35→
    36→/**
    37→ * Validates one or more YAML files for syntax and basic structural integrity.
    38→ *
    39→ * Uses bun:yaml parser which detects:
    40→ * - Syntax errors (unclosed quotes, invalid indentation, malformed pairs)
    41→ * - Structural errors (duplicate keys in mappings)
    42→ *
    43→ * @param filePaths - Array of file paths to validate
    44→ * @returns Promise resolving to array of ValidationResult objects, one per file
    45→ *
    46→ * @example
    47→ * const results = await validateYamlFiles(['config.yml', 'db.yml']);
    48→ * results.forEach(r => {
    49→ *   if (!r.valid) console.log(`${r.file} has errors:`, r.errors);
    50→ * });
    51→ */
    52→export async function validateYamlFiles(
    53→  filePaths: string[]
    54→): Promise<ValidationResult[]> {
    55→  let parseYaml: (content: string) => unknown;
    56→
    57→  try {
    58→    const yaml = await import("bun:yaml");
    59→    parseYaml = yaml.parse || yaml.default?.parse;
    60→  } catch {
    61→    parseYaml = parseYamlFallback;
    62→  }
    63→
    64→  const results: ValidationResult[] = [];
    65→
    66→  for (const filePath of filePaths) {
    67→    try {
    68→      const file = Bun.file(filePath);
    69→      const content = await file.text();
    70→
    71→      try {
    72→        parseYaml(content);
    73→
    74→        results.push({
    75→          file: filePath,
    76→          valid: true,
    77→          errors: [],
    78→        });
    79→      } catch (parseError) {
    80→        const errors = extractParseErrors(filePath, parseError);
    81→        results.push({
    82→          file: filePath,
    83→          valid: false,
    84→          errors,
    85→        });
    86→      }
    87→    } catch (error) {
    88→      const errorMessage =
    89→        error instanceof Error ? error.message : String(error);
    90→      results.push({
    91→        file: filePath,
    92→        valid: false,
    93→        errors: [
    94→          {
    95→            file: filePath,
    96→            message: errorMessage,
    97→            severity: "error",
    98→          },
    99→        ],
   100→      });
   101→    }
   102→  }
   103→
   104→  return results;
   105→}
   106→
   107→/**
   108→ * Fallback YAML parser for test environments where bun:yaml is not available.
   109→ * Provides basic YAML syntax checking and duplicate key detection.
   110→ */
   111→function parseYamlFallback(content: string): unknown {
   112→  const lines = content.split("\n");
   113→  const stack: Array<{ level: number; keys: Set<string>; inList: boolean }> = [{ level: -1, keys: new Set(), inList: false }];
   114→
   115→  for (let i = 0; i < lines.length; i++) {
   116→    const line = lines[i];
   117→    const trimmed = line.trim();
   118→
   119→    // Skip empty lines and comments
   120→    if (!trimmed || trimmed.startsWith("#")) {
   121→      continue;
   122→    }
   123→
   124→    // Calculate indentation level
   125→    const leadingSpaces = line.match(/^( *)/)?.[0].length ?? 0;
   126→    const level = Math.floor(leadingSpaces / 2);
   127→
   128→    // Check if this is a list item
   129→    const isListItem = trimmed.startsWith("-");
   130→
   131→    // Pop stack if we're at a lower indentation level
   132→    while (stack.length > 1 && level <= stack[stack.length - 1].level) {
   133→      stack.pop();
   134→    }
   135→
   136→    // If this is a list item, create a new scope for its contents
   137→    if (isListItem) {
   138→      stack.push({ level, keys: new Set(), inList: true });
   139→      // Check if the list item has inline content (e.g., "- name: value")
   140→      const contentAfterDash = trimmed.substring(1).trim();
   141→      if (contentAfterDash && contentAfterDash.includes(":")) {
   142→        // Handle inline key:value in list item
   143→        const keyMatch = contentAfterDash.match(/^([^:\s]+):/);
   144→        if (keyMatch) {
   145→          const key = keyMatch[1].replace(/^['"']|['"']$/g, "");
   146→          stack[stack.length - 1].keys.add(key);
   147→        }
   148→      }
   149→      continue;
   150→    }
   151→
   152→    // Extract key from line
   153→    const keyMatch = trimmed.match(/^([^:\s]+):/);
   154→    if (keyMatch) {
   155→      const key = keyMatch[1].replace(/^['"']|['"']$/g, "");
   156→
   157→      // Check for duplicate keys at the same level (unless we're in a list)
   158→      const currentLevelObj = stack[stack.length - 1];
   159→      if (!currentLevelObj.inList && currentLevelObj.keys.has(key)) {
   160→        throw new Error(
   161→          `duplicate key '${key}' at line ${i + 1}, column 1:\n` +
   162→          `${trimmed}\n^\n`
   163→        );
   164→      }
   165→
   166→      // Only track keys in non-list contexts at this level
   167→      if (!currentLevelObj.inList) {
   168→        currentLevelObj.keys.add(key);
   169→      }
   170→
   171→      // If there's a nested structure, push to stack
   172→      if (trimmed.endsWith(":") && trimmed.length > key.length + 1) {
   173→        stack.push({ level, keys: new Set(), inList: false });
   174→      }
   175→    }
   176→
   177→    // Check for unclosed quotes
   178→    let inDoubleQuote = false;
   179→    let inSingleQuote = false;
   180→    for (let j = 0; j < trimmed.length; j++) {
   181→      const char = trimmed[j];
   182→      const prevChar = j > 0 ? trimmed[j - 1] : "";
   183→
   184→      if (char === '"' && prevChar !== "\\") {
   185→        inDoubleQuote = !inDoubleQuote;
   186→      } else if (char === "'" && prevChar !== "\\") {
   187→        inSingleQuote = !inSingleQuote;
   188→      }
   189→    }
   190→
   191→    if (inDoubleQuote || inSingleQuote) {
   192→      throw new Error(
   193→        `Unclosed quoted string at line ${i + 1}\n` +
   194→        `${trimmed}\n`
   195→      );
   196→    }
   197→  }
   198→
   199→  return {};
   200→}
   201→
   202→/**
   203→ * Extracts structured error information from YAML parser errors.
   204→ *
   205→ * @param filePath - The file path (used in error messages)
   206→ * @param error - The error thrown by the YAML parser
   207→ * @returns Array of ValidationError objects
   208→ */
   209→function extractParseErrors(filePath: string, error: unknown): ValidationError[] {
   210→  const errorMessage = error instanceof Error ? error.message : String(error);
   211→
   212→  const lineMatch = errorMessage.match(/line (\d+)/);
   213→  const columnMatch = errorMessage.match(/column (\d+)/);
   214→
   215→  return [
   216→    {
   217→      file: filePath,
   218→      line: lineMatch ? parseInt(lineMatch[1], 10) : undefined,
   219→      column: columnMatch ? parseInt(columnMatch[1], 10) : undefined,
   220→      message: errorMessage,
   221→      severity: "error",
   222→    },
   223→  ];
   224→}
   225→
   226→
   227→/**
   228→ * Formats validation results into a human-readable output string.
   229→ *
   230→ * Produces output in the format:
   231→ *   filename.yml: line 5 - error description
   232→ *
   233→ * @param results - Array of ValidationResult objects to format
   234→ * @returns Formatted string suitable for console output
   235→ */
   236→export function formatErrors(results: ValidationResult[]): string {
   237→  const lines: string[] = [];
   238→
   239→  for (const result of results) {
   240→    for (const error of result.errors) {
   241→      if (error.line) {
   242→        lines.push(`${result.file}: line ${error.line} - ${error.message}`);
   243→      } else {
   244→        lines.push(`${result.file}: ${error.message}`);
   245→      }
   246→    }
   247→  }
   248→
   249→  return lines.join("\n");
   250→}
