/**
 * Attempts to find the line number where a key appears in YAML content.
 *
 * Uses a simple heuristic: finds the first occurrence of "key:" in the content.
 * More sophisticated tracking would require full AST analysis.
 *
 * @param content - The original YAML content
 * @param path - The path to the key (e.g., ['root', 'nested'])
 * @returns Line number (1-indexed), or undefined if not found
 */
function findLineNumber(content: string, path: string[]): number | undefined {
  if (path.length === 0) return undefined;

  const lines = content.split("\n");
  const searchKey = path[path.length - 1];

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes(`${searchKey}:`)) {
      return i + 1; // 1-indexed line numbers
    }
  }

  return undefined;
}

/**
 * Extracts line number from a YAML parser error message.
 *
 * Looks for patterns like "at line 5" or "line 5, column 3" in error messages.
 *
 * @param message - The error message string
 * @returns Line number if found, undefined otherwise
 */
function extractLineNumber(message: string): number | undefined {
  const match = message.match(/at line (\d+)/);
  if (match) return parseInt(match[1], 10);

  const match2 = message.match(/line (\d+),/);
  if (match2) return parseInt(match2[1], 10);

  return undefined;
}

