export async function validateYamlFiles(
  filePaths: string[]
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    try {
      const file = Bun.file(filePath);
      const content = await file.text();

      let parsed: unknown;
      let parseError: ValidationError | null = null;

      try {
        parsed = parseYaml(content);
      } catch (error) {
        const errorObj = error as Record<string, unknown>;
        const rawMessage = (errorObj.message as string) ?? String(error);
        // Extract just the first line of the error message for clarity
        const cleanMessage = rawMessage.split("\n")[0];
        const line = extractLineNumber(rawMessage);

        parseError = {
          file: filePath,
          line: line ?? (errorObj.line as number),
          column: (errorObj.column as number) ?? undefined,
          message: cleanMessage,
          severity: "error",
        };
      }

      if (parseError) {
        results.push({
          file: filePath,
          valid: false,
          errors: [parseError],
        });
      } else {
        const structuralErrors = validateStructure(filePath, parsed, content);
        results.push({
          file: filePath,
          valid: structuralErrors.length === 0,
          errors: structuralErrors,
        });
      }
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      results.push({
        file: filePath,
        valid: false,
        errors: [
          {
            file: filePath,
            message: errorMessage,
            severity: "error",
          },
        ],
      });
    }
  }

  return results;
}

