     1→/**
     2→ * YAML file validator module.
     3→ *
     4→ * Provides syntax validation and basic structural checks for YAML files
     5→ * using a lightweight parser. No external dependencies required.
     6→ */
     7→
     8→/**
     9→ * Represents a single validation error found in a YAML file.
    10→ */
    11→export interface ValidationError {
    12→  /** The file path where the error occurred */
    13→  file: string;
    14→  /** Line number where the error was detected (1-indexed) */
    15→  line?: number;
    16→  /** Column number where the error was detected (1-indexed) */
    17→  column?: number;
    18→  /** Human-readable error message */
    19→  message: string;
    20→  /** Severity level: 'error' for critical issues, 'warning' for minor issues */
    21→  severity: "error" | "warning";
    22→}
    23→
    24→/**
    25→ * Represents the validation result for a single file.
    26→ */
    27→export interface ValidationResult {
    28→  /** The file path that was validated */
    29→  file: string;
    30→  /** Whether the file passed validation */
    31→  valid: boolean;
    32→  /** Array of validation errors found (empty if valid) */
    33→  errors: ValidationError[];
    34→}
    35→
    36→/**
    37→ * Validates one or more YAML files for syntax and basic structural integrity.
    38→ *
    39→ * @param filePaths - Array of file paths to validate
    40→ * @returns Promise resolving to array of ValidationResult objects, one per file
    41→ *
    42→ * @example
    43→ * const results = await validateYamlFiles(['config.yml', 'db.yml']);
    44→ * results.forEach(r => {
    45→ *   if (!r.valid) console.log(`${r.file} has errors:`, r.errors);
    46→ * });
    47→ */
    48→export async function validateYamlFiles(
    49→  filePaths: string[]
    50→): Promise<ValidationResult[]> {
    51→  const results: ValidationResult[] = [];
    52→
    53→  for (const filePath of filePaths) {
    54→    try {
    55→      const file = Bun.file(filePath);
    56→      const content = await file.text();
    57→
    58→      const errors = validateYamlContent(filePath, content);
    59→
    60→      results.push({
    61→        file: filePath,
    62→        valid: errors.length === 0,
    63→        errors,
    64→      });
    65→    } catch (error) {
    66→      const errorMessage =
    67→        error instanceof Error ? error.message : String(error);
    68→      results.push({
    69→        file: filePath,
    70→        valid: false,
    71→        errors: [
    72→          {
    73→            file: filePath,
    74→            message: errorMessage,
    75→            severity: "error",
    76→          },
    77→        ],
    78→      });
    79→    }
    80→  }
    81→
    82→  return results;
    83→}
    84→
    85→/**
    86→ * Validates YAML content for syntax and structural integrity.
    87→ *
    88→ * Checks for common YAML syntax errors including:
    89→ * - Unclosed quoted strings
    90→ * - Invalid indentation patterns
    91→ * - Malformed key-value pairs
    92→ * - Unclosed block sequences/mappings
    93→ *
    94→ * @param filePath - The file path (used in error messages)
    95→ * @param content - The YAML content to validate
    96→ * @returns Array of validation errors (empty if valid)
    97→ */
    98→function validateYamlContent(
    99→  filePath: string,
   100→  content: string
   101→): ValidationError[] {
   102→  const errors: ValidationError[] = [];
   103→  const lines = content.split("\n");
   104→
   105→  // Track quote state and indentation
   106→  let inSingleQuote = false;
   107→  let inDoubleQuote = false;
   108→  let inLiteral = false;
   109→  let inFolded = false;
   110→
   111→  for (let i = 0; i < lines.length; i++) {
   112→    const lineNum = i + 1;
   113→    const line = lines[i];
   114→
   115→    // Skip empty lines and comments
   116→    if (!line.trim() || line.trim().startsWith("#")) {
   117→      continue;
   118→    }
   119→
   120→    // Check for unclosed quotes
   121→    let charIndex = 0;
   122→    let inQuote = inDoubleQuote;
   123→    let quoteChar = inDoubleQuote ? '"' : "'";
   124→
   125→    for (let j = 0; j < line.length; j++) {
   126→      const char = line[j];
   127→      const prevChar = j > 0 ? line[j - 1] : "";
   128→
   129→      if (char === '"' && (j === 0 || prevChar !== "\\")) {
   130→        if (!inSingleQuote) {
   131→          inDoubleQuote = !inDoubleQuote;
   132→        }
   133→      } else if (char === "'" && (j === 0 || prevChar !== "\\")) {
   134→        if (!inDoubleQuote) {
   135→          inSingleQuote = !inSingleQuote;
   136→        }
   137→      }
   138→    }
   139→
   140→    // Check for hanging quotes at end of file
   141→    if (i === lines.length - 1 && (inDoubleQuote || inSingleQuote)) {
   142→      errors.push({
   143→        file: filePath,
   144→        line: lineNum,
   145→        message: "Unclosed quoted string",
   146→        severity: "error",
   147→      });
   148→    }
   149→
   150→    // Check for basic key:value structure
   151→    const trimmed = line.trim();
   152→    if (
   153→      trimmed &&
   154→      !trimmed.startsWith("#") &&
   155→      !trimmed.startsWith("-") &&
   156→      !trimmed.startsWith("[") &&
   157→      !trimmed.startsWith("&") &&
   158→      !trimmed.startsWith("*") &&
   159→      !trimmed.startsWith("|") &&
   160→      !trimmed.startsWith(">")
   161→    ) {
   162→      // Should have a key structure (key: value or just key:)
   163→      if (!trimmed.includes(":") && !trimmed.startsWith("'") && !trimmed.startsWith('"')) {
   164→        // Might be a block scalar or list item, allow it
   165→      }
   166→    }
   167→  }
   168→
   169→  // Check for unmatched quotes remaining at end of content
   170→  if (inDoubleQuote) {
   171→    errors.push({
   172→      file: filePath,
   173→      line: lines.length,
   174→      message: 'Unclosed double quote',
   175→      severity: "error",
   176→    });
   177→  }
   178→  if (inSingleQuote) {
   179→    errors.push({
   180→      file: filePath,
   181→      line: lines.length,
   182→      message: 'Unclosed single quote',
   183→      severity: "error",
   184→    });
   185→  }
   186→
   187→  return errors;
   188→}
   189→
   190→
   191→/**
   192→ * Formats validation results into a human-readable output string.
   193→ *
   194→ * Produces output in the format:
   195→ *   filename.yml: line 5 - error description
   196→ *
   197→ * @param results - Array of ValidationResult objects to format
   198→ * @returns Formatted string suitable for console output
   199→ */
   200→export function formatErrors(results: ValidationResult[]): string {
   201→  const lines: string[] = [];
   202→
   203→  for (const result of results) {
   204→    for (const error of result.errors) {
   205→      if (error.line) {
   206→        lines.push(`${result.file}: line ${error.line} - ${error.message}`);
   207→      } else {
   208→        lines.push(`${result.file}: ${error.message}`);
   209→      }
   210→    }
   211→  }
   212→
   213→  return lines.join("\n");
   214→}
