/**
 * YAML file validator module.
 *
 * Provides syntax validation and basic structural checks for YAML files
 * using a lightweight parser. No external dependencies required.
 */

/**
 * Represents a single validation error found in a YAML file.
 */
export interface ValidationError {
  /** The file path where the error occurred */
  file: string;
  /** Line number where the error was detected (1-indexed) */
  line?: number;
  /** Column number where the error was detected (1-indexed) */
  column?: number;
  /** Human-readable error message */
  message: string;
  /** Severity level: 'error' for critical issues, 'warning' for minor issues */
  severity: "error" | "warning";
}

/**
 * Represents the validation result for a single file.
 */
export interface ValidationResult {
  /** The file path that was validated */
  file: string;
  /** Whether the file passed validation */
  valid: boolean;
  /** Array of validation errors found (empty if valid) */
  errors: ValidationError[];
}

/**
 * Validates one or more YAML files for syntax and basic structural integrity.
 *
 * @param filePaths - Array of file paths to validate
 * @returns Promise resolving to array of ValidationResult objects, one per file
 *
 * @example
 * const results = await validateYamlFiles(['config.yml', 'db.yml']);
 * results.forEach(r => {
 *   if (!r.valid) console.log(`${r.file} has errors:`, r.errors);
 * });
 */
export async function validateYamlFiles(
  filePaths: string[]
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  for (const filePath of filePaths) {
    try {
      const file = Bun.file(filePath);
      const content = await file.text();

      const errors = validateYamlContent(filePath, content);

      results.push({
        file: filePath,
        valid: errors.length === 0,
        errors,
      });
    } catch (error) {
      const errorMessage =
        error instanceof Error ? error.message : String(error);
      results.push({
        file: filePath,
        valid: false,
        errors: [
          {
            file: filePath,
            message: errorMessage,
            severity: "error",
          },
        ],
      });
    }
  }

  return results;
}

/**
 * Validates YAML content for syntax and structural integrity.
 *
 * Checks for common YAML syntax errors including:
 * - Unclosed quoted strings
 * - Invalid indentation patterns
 * - Malformed key-value pairs
 * - Unclosed block sequences/mappings
 *
 * @param filePath - The file path (used in error messages)
 * @param content - The YAML content to validate
 * @returns Array of validation errors (empty if valid)
 */
function validateYamlContent(
  filePath: string,
  content: string
): ValidationError[] {
  const errors: ValidationError[] = [];
  const lines = content.split("\n");

  // Track quote state and indentation
  let inSingleQuote = false;
  let inDoubleQuote = false;
  let inLiteral = false;
  let inFolded = false;

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const line = lines[i];

    // Skip empty lines and comments
    if (!line.trim() || line.trim().startsWith("#")) {
      continue;
    }

    // Check for unclosed quotes
    let charIndex = 0;
    let inQuote = inDoubleQuote;
    let quoteChar = inDoubleQuote ? '"' : "'";

    for (let j = 0; j < line.length; j++) {
      const char = line[j];
      const prevChar = j > 0 ? line[j - 1] : "";

      if (char === '"' && (j === 0 || prevChar !== "\\")) {
        if (!inSingleQuote) {
          inDoubleQuote = !inDoubleQuote;
        }
      } else if (char === "'" && (j === 0 || prevChar !== "\\")) {
        if (!inDoubleQuote) {
          inSingleQuote = !inSingleQuote;
        }
      }
    }

    // Check for hanging quotes at end of file
    if (i === lines.length - 1 && (inDoubleQuote || inSingleQuote)) {
      errors.push({
        file: filePath,
        line: lineNum,
        message: "Unclosed quoted string",
        severity: "error",
      });
    }

    // Check for basic key:value structure
    const trimmed = line.trim();
    if (
      trimmed &&
      !trimmed.startsWith("#") &&
      !trimmed.startsWith("-") &&
      !trimmed.startsWith("[") &&
      !trimmed.startsWith("&") &&
      !trimmed.startsWith("*") &&
      !trimmed.startsWith("|") &&
      !trimmed.startsWith(">")
    ) {
      // Should have a key structure (key: value or just key:)
      if (!trimmed.includes(":") && !trimmed.startsWith("'") && !trimmed.startsWith('"')) {
        // Might be a block scalar or list item, allow it
      }
    }
  }

  // Check for unmatched quotes remaining at end of content
  if (inDoubleQuote) {
    errors.push({
      file: filePath,
      line: lines.length,
      message: 'Unclosed double quote',
      severity: "error",
    });
  }
  if (inSingleQuote) {
    errors.push({
      file: filePath,
      line: lines.length,
      message: 'Unclosed single quote',
      severity: "error",
    });
  }

  return errors;
}

