/**
 * Fallback YAML parser for test environments where bun:yaml is not available.
 * Provides basic YAML syntax checking and duplicate key detection.
 */
function parseYamlFallback(content: string): unknown {
  const lines = content.split("\n");
  const stack: Array<{ level: number; keys: Set<string> }> = [{ level: -1, keys: new Set() }];
  let currentLevel = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith("#")) {
      continue;
    }

    // Calculate indentation level
    const leadingSpaces = line.match(/^( *)/)?.[0].length ?? 0;
    const level = Math.floor(leadingSpaces / 2);

    // Pop stack if we're at a lower indentation level
    while (stack.length > 1 && level <= stack[stack.length - 1].level) {
      stack.pop();
    }

    // Extract key from line
    const keyMatch = trimmed.match(/^([^:\s]+):/);
    if (keyMatch) {
      const key = keyMatch[1].replace(/^['"']|['"']$/g, "");

      // Check for duplicate keys at the same level
      const currentLevelObj = stack[stack.length - 1];
      if (currentLevelObj.keys.has(key)) {
        throw new Error(
          `Map keys must be unique at line ${i + 1}, column 1:\n` +
          `${trimmed}\n^\n`
        );
      }

      currentLevelObj.keys.add(key);

      // If there's a nested structure, push to stack
      if (trimmed.endsWith(":") && trimmed.length > key.length + 1) {
        stack.push({ level, keys: new Set() });
      }
    }

    // Check for unclosed quotes
    let inDoubleQuote = false;
    let inSingleQuote = false;
    for (let j = 0; j < trimmed.length; j++) {
      const char = trimmed[j];
      const prevChar = j > 0 ? trimmed[j - 1] : "";

      if (char === '"' && prevChar !== "\\") {
        inDoubleQuote = !inDoubleQuote;
      } else if (char === "'" && prevChar !== "\\") {
        inSingleQuote = !inSingleQuote;
      }
    }

    if (inDoubleQuote || inSingleQuote) {
      throw new Error(
        `Unclosed quoted string at line ${i + 1}\n` +
        `${trimmed}\n`
      );
    }
  }

  return {};
}

