import { describe, expect, test, beforeEach, afterEach } from "bun:test";
import { validateYamlFiles, formatErrors } from "./yaml-validator";
import { promises as fs } from "fs";
import { join } from "path";

// Create a temporary directory for test files
const TEST_DIR = "/tmp/yaml-validator-tests";

describe("yaml-validator", () => {
  beforeEach(async () => {
    // Create test directory
    await fs.mkdir(TEST_DIR, { recursive: true });
  });

  afterEach(async () => {
    // Clean up test files
    try {
      const files = await fs.readdir(TEST_DIR);
      for (const file of files) {
        await fs.unlink(join(TEST_DIR, file));
      }
      await fs.rmdir(TEST_DIR);
    } catch (error) {
      // Ignore cleanup errors
    }
  });

  describe("validateYamlFiles", () => {
    test("valid YAML file parses successfully without errors", async () => {
      const testFile = join(TEST_DIR, "valid.yml");
      const content = `name: test
version: 1.0
items:
  - item1
  - item2`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(testFile);
      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("simple valid YAML object is parsed correctly", async () => {
      const testFile = join(TEST_DIR, "simple.yml");
      const content = `key: value
number: 42
boolean: true`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(true);
      expect(results[0].errors).toHaveLength(0);
    });

    test("invalid YAML syntax is detected and reported with error message", async () => {
      const testFile = join(TEST_DIR, "invalid.yml");
      const content = `name: test
unclosed_quote: "value
another_key: value`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results).toHaveLength(1);
      expect(results[0].file).toBe(testFile);
      expect(results[0].valid).toBe(false);
      expect(results[0].errors.length).toBeGreaterThan(0);
      expect(results[0].errors[0].message).toBeDefined();
      expect(results[0].errors[0].severity).toBe("error");
    });

    test("invalid YAML syntax error includes line information when available", async () => {
      const testFile = join(TEST_DIR, "invalid-with-line.yml");
      const content = `name: test
unclosed: "value
another: key`;

      await fs.writeFile(testFile, content);

      const results = await validateYamlFiles([testFile]);

      expect(results[0].valid).toBe(false);
      expect(results[0].errors.length).toBeGreaterThan(0);
      // Line number may or may not be available depending on parser
      // but message should always be present
      expect(results[0].errors[0].message.length).toBeGreaterThan(0);
    });

    test("bad indentation is detected as syntax error", async () => {
      const testFile = join(TEST_DIR, "bad-indent.yml");
      const content = `name: test
  bad_indent: value
  another: value

{
  "success": true,
  "tool": "emit",
  "data": {
    "eventId": 16,
    "runId": "bea47895-7c17-4441-83da-24fb927be30b",
    "type": "status_change",
    "runStatus": "completed"
  }
}

{
  "success": true,
  "tool": "emit",
  "data": {
    "eventId": 18,
    "runId": "bea47895-7c17-4441-83da-24fb927be30b",
    "type": "status_change",
    "skippedSteps": [
      "verify"
    ],
    "runStatus": "running"
  }
}

{
  "success": true,
  "tool": "emit",
  "data": {
    "eventId": 19,
    "runId": "bea47895-7c17-4441-83da-24fb927be30b",
